import{z as i,x as d,o as l,c as A,q as o,j as s,D as e,d as E,s as B,S as r,b as n}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"最近点对","description":"","frontmatter":{"title":"最近点对","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/closest-pair.md","filePath":"cs/closest-pair.md","lastUpdated":1791063341000}'),p={name:"cs/closest-pair.md"};function m(C,a,h,c,D,_){const t=d("Mermaid");return l(),A("div",null,[a[2]||(a[2]=o('<h1 id="最近点对" tabindex="-1">最近点对 <a class="header-anchor" href="#最近点对" aria-label="Permalink to &quot;最近点对&quot;">​</a></h1><div class="epigraph"><p>平面最近点对可分治：$O(n\\log n)$ 排序后，中线带宽内最多常数个候选，总 $T(n)=2T(n/2)+O(n)$。</p><footer>—— 据 Shamos and Hoey, Closest-Point Problems, 1975；CLRS 第 33.4 节整理</footer></div><p>上一课<a href="/cs/sweep-line">扫描线</a>处理覆盖问题。现在要最近点对 \\(\\min_{i\\neq j}\\|p_i-p_j\\|\\)：朴素两两比较是 \\(O(n^2)\\)。缺口是分治：按 \\(x\\) 中位数切开，两侧各递归出 \\(\\delta\\)，再只扫中线附近带宽 \\(2\\delta\\) 的竖条。本课不重写旋转卡壳（那是最远点对）；后课线段相交。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>左右各递归得 \\(\\delta=\\min(\\delta_L,\\delta_R)\\)；把中线附近宽 \\(2\\delta\\) 的点按 \\(y\\) 归并排序；条内每个点只与 \\(y\\) 序后继的常数个点比较——格论证说至多 7 个。总式 \\(T(n)=2T(n/2)+O(n)\\)，即 \\(O(n\\log n)\\)。<span class="marginnote">数字实例：\\(n=100\\) 万个点，朴素两两比较约要做 \\(10^{12}\\) 次距离计算；\\(O(n\\log n)\\) 大约是 \\(10^6 \\times 20 = 2\\times 10^7\\) 次——差五个数量级，这就是「中带常数候选」这一论证换来的收益。</span></p><p>扫描线：平衡树按 \\(y\\) 维护距左 \\(\\delta\\) 的点，同样 \\(O(n\\log n)\\)。</p><p>缺口是「带宽内常数候选」这个论证，不是旋转卡壳。</p><h3 id="最远点对不是本课" tabindex="-1">最远点对不是本课 <a class="header-anchor" href="#最远点对不是本课" aria-label="Permalink to &quot;最远点对不是本课&quot;">​</a></h3><p>最远点对住在凸包直径上，用旋转卡壳求；最近点对通常在内部，与凸包无关。不要混。</p><p><span class="marginnote">Shamos–Hoey 1975。CLRS 33.4。后课 BO 线段交。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现：先按 \\(x\\) 预排序；递归用归并维持 \\(y\\) 序，免得每层重新排序；或者一上手就扫描线加按 \\(y\\) 组织的平衡树，\\(\\delta\\) 收紧时顺手删掉离扫描线超 \\(\\delta\\) 的点。注意重合点：距离为 \\(0\\)，先判重。<span class="marginnote">常见误区：直接写递归、每层重新排序——单层就付 \\(O(n\\log n)\\)，总复杂度退回 \\(O(n\\log^2 n)\\)。正确姿势是递归时用归并把 \\(y\\) 序「顺手」合并出来；另外开口先判重合点，否则两个重合点会让答案平凡地是 0，程序却可能还在条带里白忙。</span></p>',12)),(l(),s(r,null,{default:e(()=>[B(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%8C%89%20x%20%E5%88%86%E6%B2%BB%22%5D%20--%3E%20D%5B%22%E5%B7%A6%E5%8F%B3%20%CE%B4%22%5D%0A%20%20D%20--%3E%20STR%5B%22%E4%B8%AD%E5%B8%A6%E6%8C%89%20y%22%5D%0A%20%20STR%20--%3E%20NN%5B%22%E6%9C%80%E8%BF%91%E7%82%B9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"三维以上仍可分治：中带内的候选对仍被常数上限截住，只是常数随维数变大，实现也更繁。",-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[E("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,"机制是鸽笼论证：把条带切成 \\(\\delta\\times\\delta\\) 的方格，任一方格里同侧至多一点——否则该侧两点距离已 \\(\\lt\\delta\\)，矛盾；于是每个点沿 \\(y\\) 方向至多与常数个点可能成对，线性合并步保住了。配主定理得 \\(O(n\\log n)\\)。随机哈希网格（点撒进格子、只查邻格）期望线性，点名。",-1)),(l(),s(r,null,{default:e(()=>[B(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20STRIP%5B%22%E4%B8%AD%E7%BA%BF%E4%B8%A4%E4%BE%A7%E5%90%84%E5%AE%BD%20%CE%B4%20%E7%9A%84%E7%AB%96%E6%9D%A1%E5%B8%A6%22%5D%20--%3E%20GRID%5B%22%E5%88%87%E6%88%90%20%CE%B4%C3%97%CE%B4%20%E7%9A%84%E5%B0%8F%E6%96%B9%E6%A0%BC%22%5D%0A%20%20GRID%20--%3E%20CAGE%5B%22%E5%90%8C%E4%BE%A7%E4%BB%BB%E6%84%8F%E4%B8%A4%E7%82%B9%E8%B7%9D%E7%A6%BB%E9%83%BD%20%E2%89%A5%20%CE%B4%EF%BC%8C%E4%B8%80%E6%A0%BC%E8%A3%85%E4%B8%8D%E4%B8%8B%E5%87%A0%E4%B8%AA%22%5D%0A%20%20CAGE%20--%3E%20CAND%5B%22%E6%AF%8F%E4%B8%AA%E7%82%B9%E5%8F%AA%E9%9C%80%E6%9F%A5%20y%20%E6%96%B9%E5%90%91%E4%B8%8A%E4%B8%8B%E5%87%A0%E6%A0%BC%E9%87%8C%E7%9A%84%E7%82%B9%22%5D%0A%20%20CAND%20--%3E%20CONST%5B%22%E5%80%99%E9%80%89%E8%A2%AB%E9%92%89%E6%AD%BB%E5%9C%A8%E5%B8%B8%E6%95%B0%E4%B8%AA%EF%BC%88%E7%BB%8F%E5%85%B8%E7%95%8C%207%EF%BC%89%22%5D%0A%20%20CONST%20--%3E%20LIN%5B%22%E5%90%88%E5%B9%B6%E6%AD%A5%20O(n)%EF%BC%8C%E4%B8%BB%E5%AE%9A%E7%90%86%E6%94%B6%E5%B0%BE%20O(n%20log%20n)%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">这张图回答「为什么条带里不会冒出海量候选」。直觉类比鸽笼论证：格子里若塞进两个同侧点，它俩的距离必然小于格子尺寸，与「同侧点至少相距 δ」矛盾——每格几乎独占，候选才恒为常数。这一步是整个 \\(O(n\\log n)\\) 的承重墙。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写高维最近点的复杂度阶梯，不写带插入删除的动态最近点。后课默认：平面最近点对 \\(O(n\\log n)\\)。下一课 Bentley–Ottmann。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分治中带常数比较。</li><li>\\(O(n\\log n)\\)；最远走凸包。</li><li>扫描线变体同类。</li><li>出处：Shamos and Hoey, 1975；CLRS 第 33.4 节。</li></ul>',5))])}const f=i(p,[["render",m]]);export{T as __pageData,f as default};
